      out.write("<script>\r\n");
      out.write("    function togglePassword(inputId, btn) {\r\n");
      out.write("        const input = document.getElementById(inputId);\r\n");
      out.write("        input.type  = (input.type === 'password') ? 'text' : 'password';\r\n");
      out.write("        btn.textContent = (input.type === 'text') ? 'ðŸ™ˆ' : 'ðŸ‘';\r\n");
      out.write("    }\r\n");
      out.write("\r\n");
      out.write("    function checkStrength(password) {\r\n");
      out.write("        const fill  = document.getElementById('strengthFill');\r\n");
      out.write("        const label = document.getElementById('strengthLabel');\r\n");
      out.write("        let score   = 0;\r\n");
      out.write("\r\n");
      out.write("        if (password.length >= 8)              score++;\r\n");
      out.write("        if (/[A-Z]/.test(password))            score++;\r\n");
      out.write("        if (/[0-9]/.test(password))            score++;\r\n");
      out.write("        if (/[^A-Za-z0-9]/.test(password))     score++;\r\n");
      out.write("\r\n");
      out.write("        const levels = [\r\n");
      out.write("            { pct: '0%',   color: 'transparent', text: '' },\r\n");
      out.write("            { pct: '25%',  color: '#F85149',     text: 'Weak' },\r\n");
      out.write("            { pct: '50%',  color: '#D29922',      text: 'Fair' },\r\n");
      out.write("            { pct: '75%',  color: '#58A6FF',      text: 'Good' },\r\n");
      out.write("            { pct: '100%', color: '#3FB950',      text: 'Strong' },\r\n");
      out.write("        ];\r\n");
      out.write("\r\n");
      out.write("        fill.style.width      = levels[score].pct;\r\n");
